insert into passages (id, text, difficulty_level, b, active) values
('eae8c494-f7d8-43d5-a1d8-5c56e459ee3b', 'In recent years, beekeeping has become increasingly popular in cities around the world. Rooftop gardens, balconies, and even office buildings now host beehives, allowing urban residents to produce their own honey while supporting local pollinator populations. Advocates of urban beekeeping argue that cities can actually provide bees with a wider variety of flowering plants than rural areas, where large farms often grow only a single crop. However, keeping bees in a crowded city also presents challenges. Beekeepers must follow strict local regulations regarding hive placement to avoid conflicts with neighbors, and they need to monitor their bees closely for diseases that can spread quickly in dense urban environments. Despite these challenges, many city beekeeping clubs report growing membership each year, as more people become interested in sustainable food production and environmental conservation.', 2, -1.0, true),
('8324dead-78fd-4cff-b873-a982f04b0c86', 'Over the past decade, podcasts have grown from a niche hobby into a major form of media consumption. Unlike traditional radio, podcasts allow listeners to choose exactly what they want to hear and listen whenever it is convenient for them, whether during a commute, a workout, or household chores. This flexibility has attracted a wide range of creators, from major media companies to independent hosts recording episodes from their bedrooms. Advertisers have taken notice as well, since podcast listeners tend to be highly engaged and often listen to entire episodes without skipping ads, unlike viewers of many other media formats. Some critics worry that the growing commercial interest in podcasting could eventually reduce the creative freedom that made the medium appealing in the first place, though for now, independent podcasts continue to thrive alongside professionally produced shows.', 2, -1.0, true);
insert into questions (id, type, text, passage_id, options, correct_answer, explanation, a, b, c, difficulty_level, created_by, hint, active) values
('6eba1aa6-998f-4998-a096-2d1075e6ff01', 'sentence_completion', 'The airline apologized for the ___ delay and offered passengers a refund.', NULL, '[{"id": "b", "text": "unexpected"}, {"id": "a", "text": "planned"}, {"id": "c", "text": "short"}, {"id": "d", "text": "pleasant"}]'::jsonb, 0, '{"strategy": "apologized...offered a refund = התנצלו והציעו החזר. איזה סוג עיכוב מצדיק פיצוי?", "correct_reason": "unexpected = בלתי צפוי. עיכוב פתאומי מצדיק התנצלות והחזר.", "options_analysis": ["נכון! unexpected = בלתי צפוי — מצדיק התנצלות ופיצוי", "planned = מתוכנן — לא מצדיק התנצלות", "short = קצר — לא בהכרח מצדיק פיצוי", "pleasant = נעים — סותר את הצורך בהתנצלות"]}', 0.91, -1.0, 0.25, 2, 'ai', NULL, true),
('bf1fa28d-b924-44cc-be4b-d80277f4f461', 'sentence_completion', 'She felt ___ after receiving so much positive feedback on her project.', NULL, '[{"id": "d", "text": "discouraged"}, {"id": "c", "text": "encouraged"}, {"id": "b", "text": "bored"}, {"id": "a", "text": "confused"}]'::jsonb, 1, '{"strategy": "positive feedback = משוב חיובי. איך מרגישים אחרי משוב טוב?", "correct_reason": "encouraged = מעודדת. משוב חיובי מעודד.", "options_analysis": ["discouraged = מיואשת — הפוך ממשוב חיובי", "נכון! encouraged = מעודדת — תגובה טבעית למשוב חיובי", "bored = משועממת — לא קשור למשוב", "confused = מבולבלת — לא מתאים למשוב ברור וחיובי"]}', 1.25, -1.0, 0.25, 2, 'ai', NULL, true),
('2789731a-a81b-4c85-989d-8b6c74dd9bdd', 'sentence_completion', 'The mechanic ___ the car before returning it to its owner.', NULL, '[{"id": "c", "text": "painted"}, {"id": "b", "text": "sold"}, {"id": "a", "text": "inspected"}, {"id": "d", "text": "ignored"}]'::jsonb, 2, '{"strategy": "before returning it to its owner = לפני החזרתו לבעלים. מה עושה מוסכניק לפני החזרת רכב?", "correct_reason": "inspected = בדק. בדיקה סופית לפני החזרה הגיונית.", "options_analysis": ["painted = צבע — לא בהכרח רלוונטי", "sold = מכר — לא רלוונטי, הרכב מוחזר לבעליו", "נכון! inspected = בדק — פעולה טבעית לפני החזרת רכב", "ignored = התעלם מ- — לא הגיוני למוסכניק"]}', 0.93, -1.0, 0.25, 2, 'ai', NULL, true),
('621a1e5f-ebf2-4461-b6f3-70b71c505e0f', 'sentence_completion', 'He was ___ to find out that his flight had been cancelled.', NULL, '[{"id": "c", "text": "thrilled"}, {"id": "a", "text": "proud"}, {"id": "b", "text": "relaxed"}, {"id": "d", "text": "disappointed"}]'::jsonb, 3, '{"strategy": "flight cancelled = טיסה בוטלה. איך מרגישים כשטיסה מתבטלת?", "correct_reason": "disappointed = מאוכזב. ביטול טיסה מאכזב.", "options_analysis": ["thrilled = נרגש — הפוך מתגובה לביטול", "proud = גאה — לא קשור לביטול טיסה", "relaxed = רגוע — לא סביר לביטול פתאומי", "נכון! disappointed = מאוכזב — תגובה טבעית לביטול"]}', 1.57, -1.0, 0.25, 2, 'ai', NULL, true),
('5b1c4b3c-d1bc-4096-bf19-cb151974e4cc', 'sentence_completion', 'The city council decided to ___ the old bridge instead of repairing it.', NULL, '[{"id": "a", "text": "replace"}, {"id": "d", "text": "paint"}, {"id": "b", "text": "celebrate"}, {"id": "c", "text": "ignore"}]'::jsonb, 0, '{"strategy": "instead of repairing = במקום לתקן. מה עושים כשלא מתקנים?", "correct_reason": "replace = להחליף. אלטרנטיבה לתיקון היא החלפה.", "options_analysis": ["נכון! replace = להחליף — האלטרנטיבה הטבעית לתיקון", "paint = לצבוע — לא אלטרנטיבה לתיקון מבני", "celebrate = לחגוג — לא רלוונטי לגשר", "ignore = להתעלם מ- — לא פתרון אקטיבי"]}', 1.29, -1.0, 0.25, 2, 'ai', NULL, true),
('e5c57777-a628-4e2e-bdb5-7214e24be56d', 'sentence_completion', 'The students were asked to ___ their essays before submitting them.', NULL, '[{"id": "d", "text": "delete"}, {"id": "c", "text": "review"}, {"id": "b", "text": "copy"}, {"id": "a", "text": "sell"}]'::jsonb, 1, '{"strategy": "before submitting = לפני הגשה. מה עושים למאמר לפני הגשה סופית?", "correct_reason": "review = לעבור על/לבדוק. בדיקה לפני הגשה היא הגיונית.", "options_analysis": ["delete = למחוק — סותר ''submitting''", "נכון! review = לבדוק — פעולה טבעית לפני הגשה", "copy = להעתיק — לא רלוונטי להגשה עצמית", "sell = למכור — לא רלוונטי למטלה"]}', 0.97, -1.0, 0.25, 2, 'ai', NULL, true),
('9442fd56-b3fc-4194-a50b-1cdbcc4267d2', 'sentence_completion', 'The company had to ___ its plans due to a lack of funding.', NULL, '[{"id": "d", "text": "publish"}, {"id": "c", "text": "celebrate"}, {"id": "b", "text": "abandon"}, {"id": "a", "text": "expand"}]'::jsonb, 2, '{"strategy": "due to a lack of funding = בגלל חוסר מימון. מה קורה לתוכניות בלי כסף?", "correct_reason": "abandon = לנטוש. חוסר מימון מוביל לנטישת תוכניות.", "options_analysis": ["publish = לפרסם — לא רלוונטי", "celebrate = לחגוג — לא הגיוני בהעדר מימון", "נכון! abandon = לנטוש — תוצאה הגיונית לחוסר מימון", "expand = להרחיב — הפוך, אין מימון להרחבה"]}', 1.49, -1.0, 0.25, 2, 'ai', NULL, true),
('b993f72f-cc6c-4ada-bad7-7ba3bb39682a', 'sentence_completion', 'The weather forecast ___ heavy rain for the entire weekend.', NULL, '[{"id": "a", "text": "canceled"}, {"id": "b", "text": "ignored"}, {"id": "d", "text": "celebrated"}, {"id": "c", "text": "predicted"}]'::jsonb, 3, '{"strategy": "weather forecast = תחזית מזג אוויר. מה עושה תחזית?", "correct_reason": "predicted = חזתה. תפקיד התחזית הוא לחזות.", "options_analysis": ["canceled = ביטלה — לא רלוונטי לתחזית", "ignored = התעלם מ- — סותר תפקיד תחזית", "celebrated = חגגה — לא רלוונטי לתחזית", "נכון! predicted = חזתה — התפקיד הטבעי של תחזית"]}', 1.11, -1.0, 0.25, 2, 'ai', NULL, true),
('10f0fbf0-4c7d-455a-baf2-3f5668a93f30', 'sentence_completion', 'He felt ___ after working for twelve hours straight.', NULL, '[{"id": "c", "text": "exhausted"}, {"id": "a", "text": "proud"}, {"id": "b", "text": "energetic"}, {"id": "d", "text": "relaxed"}]'::jsonb, 0, '{"strategy": "twelve hours straight = שתים עשרה שעות ברצף. איך מרגישים אחרי עבודה כה ארוכה?", "correct_reason": "exhausted = מותש. עבודה ארוכה מתישה.", "options_analysis": ["נכון! exhausted = מותש — תוצאה טבעית של עבודה ארוכה", "proud = גאה — לא בהכרח קשור לתשישות", "energetic = מלא אנרגיה — הפוך מתשישות", "relaxed = רגוע — לא סביר אחרי עבודה ארוכה"]}', 1.23, -1.0, 0.25, 2, 'ai', NULL, true),
('3e1bdf49-3b9a-4941-8bbd-bb7acee2a6e7', 'sentence_completion', 'The hikers had to ___ their trip because of the storm warning.', NULL, '[{"id": "a", "text": "extend"}, {"id": "d", "text": "cancel"}, {"id": "c", "text": "enjoy"}, {"id": "b", "text": "celebrate"}]'::jsonb, 1, '{"strategy": "storm warning = אזהרת סערה. מה עושים לטיול בגלל אזהרה?", "correct_reason": "cancel = לבטל. אזהרת סערה מובילה לביטול טיול.", "options_analysis": ["extend = להאריך — הפוך מהיגיון בטיחותי", "נכון! cancel = לבטל — תגובה בטיחותית הגיונית", "enjoy = ליהנות — לא רלוונטי לאזהרה", "celebrate = לחגוג — לא רלוונטי"]}', 1.01, -1.0, 0.25, 2, 'ai', NULL, true),
('e2fa8317-40f1-499c-8ca7-8fdd3d657a81', 'sentence_completion', 'The teacher ___ the students for arriving late to class every day.', NULL, '[{"id": "c", "text": "ignored"}, {"id": "b", "text": "thanked"}, {"id": "d", "text": "scolded"}, {"id": "a", "text": "praised"}]'::jsonb, 2, '{"strategy": "arriving late every day = מאחרים כל יום. איך מגיבה מורה לאיחור חוזר?", "correct_reason": "scolded = נזפה. איחור חוזר מוביל לנזיפה.", "options_analysis": ["ignored = התעלמה מ- — פחות סביר מנזיפה", "thanked = הודתה ל- — לא הגיוני לאיחור", "נכון! scolded = נזפה — תגובה הגיונית לאיחור חוזר", "praised = שיבחה — הפוך, איחור לא ראוי לשבח"]}', 1.21, -1.0, 0.25, 2, 'ai', NULL, true),
('3f414cf4-2750-4034-ba7a-b245f53c52a1', 'sentence_completion', 'The new employee ___ quickly to the company''s fast-paced environment.', NULL, '[{"id": "d", "text": "ignored"}, {"id": "b", "text": "complained"}, {"id": "c", "text": "refused"}, {"id": "a", "text": "adapted"}]'::jsonb, 3, '{"strategy": "quickly to...environment = הסתגל מהר לסביבה. מה קרה לעובד החדש?", "correct_reason": "adapted = הסתגל. הסתגלות מהירה לסביבה חדשה.", "options_analysis": ["ignored = התעלם מ- — לא רלוונטי", "complained = התלונן — הפוך מהסתגלות מוצלחת", "refused = סירב — לא מסביר הסתגלות", "נכון! adapted = הסתגל — מתאים ל''quickly to environment''"]}', 1.34, -1.0, 0.25, 2, 'ai', NULL, true),
('59225d5d-7990-49dd-b11e-fb0eb37c339b', 'restatement', 'He missed the bus, so he walked to work instead.', NULL, '[{"id": "c", "text": "Because he missed the bus, he walked to work."}, {"id": "d", "text": "He walked to work before missing the bus."}, {"id": "a", "text": "He missed the bus, so he stayed home."}, {"id": "b", "text": "He missed the bus because he walked to work."}]'::jsonb, 0, '{"strategy": "missed the bus, so walked = פספס אוטובוס, לכן הלך ברגל. סיבה-תוצאה.", "correct_reason": "אותה סיבה-תוצאה בדיוק.", "options_analysis": ["נכון! אותה סיבה-תוצאה בדיוק", "הופך את סדר הזמן והסיבתיות", "סותר ''walked to work instead''", "הופך סיבה ותוצאה"]}', 1.32, -1.0, 0.25, 2, 'ai', NULL, true),
('635f7afe-4be5-406e-96a1-c745dbdf7270', 'restatement', 'She studies every night, even when she is tired.', NULL, '[{"id": "a", "text": "She studies every night unless she is tired."}, {"id": "b", "text": "Even when tired, she studies every night."}, {"id": "d", "text": "She never studies at night."}, {"id": "c", "text": "She only studies when she is not tired."}]'::jsonb, 1, '{"strategy": "even when tired = גם כשעייפה. הרגל שלא נשבר מעייפות.", "correct_reason": "אותה משמעות בדיוק של ניגוד/עקביות.", "options_analysis": ["''אלא אם'' סותר את העקביות במקור", "נכון! אותה משמעות בדיוק: לומדת גם כשעייפה", "סותר ''studies every night'' לגמרי", "הפוך — במקור היא לומדת גם כשעייפה"]}', 1.03, -1.0, 0.25, 2, 'ai', NULL, true),
('27744845-eaca-4be5-8f23-304dc2f0c22f', 'restatement', 'The company hired new staff to handle the extra work.', NULL, '[{"id": "a", "text": "The company had no extra work to handle."}, {"id": "b", "text": "New staff refused to handle the extra work."}, {"id": "d", "text": "New staff were hired to handle the extra work."}, {"id": "c", "text": "The company fired staff because of extra work."}]'::jsonb, 2, '{"strategy": "hired = גייסה. פעיל לסביל.", "correct_reason": "אותה עובדה בדיוק, בקול סביל.", "options_analysis": ["סותר ''extra work'' במקור", "סותר לגמרי — נגייסו כדי לטפל בעבודה", "נכון! אותה עובדה בדיוק, בקול סביל", "הפוך — ''fired'' סותר ''hired''"]}', 1.04, -1.0, 0.25, 2, 'ai', NULL, true),
('b5c5a32e-2d39-48bb-9d43-0e9f3dec43af', 'restatement', 'He can cook well, but he rarely has time to do it.', NULL, '[{"id": "b", "text": "He never cooks because he cannot cook well."}, {"id": "c", "text": "He cannot cook well, but he has plenty of time."}, {"id": "d", "text": "He cooks well and always has time to do it."}, {"id": "a", "text": "Although he cooks well, he rarely has time to do it."}]'::jsonb, 3, '{"strategy": "can cook well, but rarely = מבשל טוב, אך לעיתים נדירות. ניגוד.", "correct_reason": "אותה משמעות בדיוק של ניגוד.", "options_analysis": ["סותר לגמרי — הוא כן יודע לבשל", "הפוך — הוא כן יודע לבשל טוב", "סותר ''rarely has time''", "נכון! אותה משמעות בדיוק: מבשל טוב אך לעיתים נדירות"]}', 1.33, -1.0, 0.25, 2, 'ai', NULL, true),
('53611bbf-8db5-4904-a154-d6a37d051610', 'restatement', 'The flight was delayed, so passengers waited at the gate.', NULL, '[{"id": "b", "text": "Passengers waited at the gate because the flight was delayed."}, {"id": "c", "text": "The flight was delayed after passengers left the gate."}, {"id": "d", "text": "Passengers caused the flight to be delayed."}, {"id": "a", "text": "The flight was on time, so passengers left the gate."}]'::jsonb, 0, '{"strategy": "delayed, so waited = התעכבה, לכן חיכו. סיבה-תוצאה.", "correct_reason": "אותה סיבה-תוצאה בדיוק.", "options_analysis": ["נכון! אותה סיבה-תוצאה בדיוק", "הופך את סדר האירועים", "הופך סיבה ותוצאה", "הפוך — ''on time'' סותר ''delayed''"]}', 1.58, -1.0, 0.25, 2, 'ai', NULL, true),
('64a25907-a0e3-42e1-b872-4e73f7bde8fe', 'restatement', 'She finished the marathon despite injuring her ankle.', NULL, '[{"id": "d", "text": "She injured her ankle after finishing the marathon."}, {"id": "b", "text": "Despite an ankle injury, she finished the marathon."}, {"id": "a", "text": "She finished the marathon before injuring her ankle."}, {"id": "c", "text": "She did not finish the marathon because of her ankle injury."}]'::jsonb, 1, '{"strategy": "despite injuring...finished = למרות פציעה, סיימה. ניגוד.", "correct_reason": "אותה משמעות בדיוק של ניגוד.", "options_analysis": ["הופך את סדר האירועים", "נכון! אותה משמעות בדיוק: סיימה למרות הפציעה", "הופך את סדר האירועים", "סותר ''finished the marathon'' — היא כן סיימה"]}', 1.48, -1.0, 0.25, 2, 'ai', NULL, true),
('41b337de-b283-4488-ad02-68cc51e23740', 'restatement', 'The library closes early on weekends.', NULL, '[{"id": "d", "text": "The library closes late on weekends."}, {"id": "a", "text": "The library never closes on weekends."}, {"id": "b", "text": "On weekends, the library closes early."}, {"id": "c", "text": "The library opens early on weekends."}]'::jsonb, 2, '{"strategy": "closes early on weekends = נסגרת מוקדם בסופ''ש. פרט זמן.", "correct_reason": "אותה עובדה בדיוק, סדר מילים הפוך.", "options_analysis": ["''מאוחר'' סותר ''early''", "''אף פעם לא נסגרת'' סותר ''closes early''", "נכון! אותה עובדה בדיוק", "''נפתחת'' סותר ''closes''"]}', 0.96, -1.0, 0.25, 2, 'ai', NULL, true),
('0433269f-0625-4d76-b7fa-d5d4271f0266', 'restatement', 'He forgot his umbrella, so he got wet in the rain.', NULL, '[{"id": "a", "text": "He got wet in the rain, so he forgot his umbrella."}, {"id": "b", "text": "He forgot his umbrella because it was raining."}, {"id": "c", "text": "He remembered his umbrella and stayed dry."}, {"id": "d", "text": "Because he forgot his umbrella, he got wet in the rain."}]'::jsonb, 3, '{"strategy": "forgot...so got wet = שכח...לכן נרטב. סיבה-תוצאה.", "correct_reason": "אותה סיבה-תוצאה בדיוק.", "options_analysis": ["הופך סיבה ותוצאה", "הופך סיבה ותוצאה", "סותר ''forgot his umbrella''", "נכון! אותה סיבה-תוצאה בדיוק"]}', 1.37, -1.0, 0.25, 2, 'ai', NULL, true),
('2ef92c2a-8515-477a-b561-0bffdc748be5', 'restatement', 'The new policy was approved after a long discussion.', NULL, '[{"id": "c", "text": "After a long discussion, the new policy was approved."}, {"id": "d", "text": "The new policy was rejected after a long discussion."}, {"id": "b", "text": "The new policy was approved without any discussion."}, {"id": "a", "text": "The discussion began after the policy was approved."}]'::jsonb, 0, '{"strategy": "approved after discussion = אושרה אחרי דיון. פרט זמן.", "correct_reason": "אותה עובדה בדיוק, סדר מילים הפוך.", "options_analysis": ["נכון! אותה עובדה בדיוק", "''נדחתה'' סותר ''approved''", "סותר ''a long discussion''", "הופך את סדר האירועים"]}', 1.37, -1.0, 0.25, 2, 'ai', NULL, true),
('5d29707c-8b87-4898-aa13-09c25933ecee', 'restatement', 'She prefers working from home rather than commuting.', NULL, '[{"id": "a", "text": "She has never tried working from home."}, {"id": "d", "text": "She would rather work from home than commute."}, {"id": "b", "text": "She refuses to work from home."}, {"id": "c", "text": "She prefers commuting to working from home."}]'::jsonb, 1, '{"strategy": "prefers X rather than Y = מעדיפה X על פני Y.", "correct_reason": "would rather X than Y = אותה עדיפות בדיוק.", "options_analysis": ["סותר את קיום ההעדפה עצמה", "נכון! אותה עדיפות בדיוק", "סותר ''prefers working from home''", "הופך את סדר העדיפות"]}', 1.11, -1.0, 0.25, 2, 'ai', NULL, true),
('ee1c3af2-c8ef-4999-aaba-afecd7eb1f2d', 'restatement', 'The team celebrated after winning the championship.', NULL, '[{"id": "a", "text": "The team lost the championship and celebrated."}, {"id": "c", "text": "The team celebrated without winning anything."}, {"id": "d", "text": "After winning the championship, the team celebrated."}, {"id": "b", "text": "The team celebrated before losing the championship."}]'::jsonb, 2, '{"strategy": "celebrated after winning = חגגו אחרי ניצחון. פרט זמן.", "correct_reason": "אותה עובדה בדיוק, סדר מילים הפוך.", "options_analysis": ["סותר ''winning the championship''", "סותר ''winning the championship''", "נכון! אותה עובדה בדיוק", "''הפסידה'' סותר ''winning''"]}', 1.44, -1.0, 0.25, 2, 'ai', NULL, true),
('e56f01cd-fcbe-4cd3-a212-f87fb58c058a', 'restatement', 'He was nervous before the interview, but he answered confidently.', NULL, '[{"id": "b", "text": "He refused to answer any questions during the interview."}, {"id": "a", "text": "He was confident before the interview and nervous during it."}, {"id": "d", "text": "He was not nervous at all before the interview."}, {"id": "c", "text": "Even though he was nervous before the interview, he answered confidently."}]'::jsonb, 3, '{"strategy": "nervous before, but confidently = עצבני לפני, אך ענה בביטחון. ניגוד.", "correct_reason": "אותה משמעות בדיוק של ניגוד.", "options_analysis": ["סותר ''answered confidently''", "הופך את סדר הרגשות", "סותר ''was nervous'' במקור", "נכון! אותה משמעות בדיוק: עצבני לפני, ענה בביטחון"]}', 0.9, -1.0, 0.25, 2, 'ai', NULL, true),
