('ca59a809-f2bf-4e52-b65a-03e62b99a335', 'reading_comprehension', 'According to the passage, why might cities provide bees with a variety of plants?', 'eae8c494-f7d8-43d5-a1d8-5c56e459ee3b', '[{"id": "c", "text": "Because farms do not allow bees at all"}, {"id": "b", "text": "Because rural farms often grow only a single crop"}, {"id": "d", "text": "Because cities have more rain than rural areas"}, {"id": "a", "text": "Because bees prefer city noise"}]'::jsonb, 1, '{"strategy": "שאלת פרט — חפש את הטענה על גיוון צמחייה בפסקה.", "correct_reason": "הפסקה אומרת: ''cities can actually provide bees with a wider variety of flowering plants than rural areas, where large farms often grow only a single crop''.", "options_analysis": ["לא נאמר בפסקה", "נכון! נאמר במפורש בפסקה", "לא נאמר בפסקה", "לא נאמר בפסקה"]}', 1.34, -1.0, 0.25, 2, 'ai', NULL, true),
